#include <stdio.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int count1 = 0, count2 = 0;
    for (int i = 0; i < n; i++) {
        int t;
        scanf("%d", &t);
        if (t == 1) {
            count1++;
        } else {
            count2++;
        }
    }

    int p, m;
    scanf("%d %d", &p, &m);

    if (count1 <= p && count2 <= m) {
        printf("S\n");
    } else {
        printf("N\n");
    }

    return 0;
}
